import { readFileSync, writeFileSync } from 'node:fs';
import { NumericTypes } from '../numeric-types.js';

const lines = [
  '// Generated by node hg/tools/generate-types.mjs. Do not edit by hand.',
  "import { Data } from './data.js';",
  "import { Types } from './types.js';",
  '',
  'export const TypeBindings = {',
  '  vectors: {',
];
for (const type of NumericTypes.vectorTypes) {
  lines.push(
    `    ${type}: (...values) => Data.vector(${NumericTypes.vectorInfo(type).size}, values, '${type}'),`,
  );
}
lines.push('  },', '  matrices: {');
for (const size of [2, 3, 4]) {
  lines.push(`    mat${size}x${size}f: (...values) => Data.matrix(${size}, values),`);
}
lines.push('  },', '  guards: {');
for (const type of [
  'num',
  'str',
  'list',
  'dict',
  'error',
  'array',
  'many',
  'texture2d',
  'binding',
  ...NumericTypes.scalarTypes,
  ...NumericTypes.vectorTypes,
  ...NumericTypes.matrixTypes,
  ...Object.keys(NumericTypes.typeAliases),
]) {
  lines.push(`    '${type}?': (...values) => {`);
  lines.push(
    `      if (values.length !== 1) throw new TypeError('${type}? expects exactly one value');`,
  );
  lines.push(`      try { Types.assertType(values[0], '${type}'); return true; }`);
  lines.push('      catch (error) { if (error instanceof TypeError) return false; throw error; }');
  lines.push('    },');
}
lines.push('  },', '};');
for (const size of [2, 3, 4]) {
  lines.push(`TypeBindings.vectors.vec${size} = TypeBindings.vectors.vec${size}f;`);
  lines.push(`TypeBindings.matrices.mat${size} = TypeBindings.matrices.mat${size}x${size}f;`);
}
lines.push('');
const source = lines.join('\n');
const destination = new URL('../type-bindings.generated.js', import.meta.url);
if (process.argv.includes('--check')) {
  if (readFileSync(destination, 'utf8').replace(/\r\n/g, '\n') !== source)
    throw new Error('Generated type bindings are stale; run node hg/tools/generate-types.mjs');
} else writeFileSync(destination, source);
